3025:model PartnerPayoutProfile {

1	"use server";
2	
3	// Admin server actions for the KOL / Agency partner program: create & manage
4	// partners and their commission rates, attach/detach customers, and settle
5	// accrued commission (mark PAID). Billing-area gated, mirroring the existing
6	// affiliate admin actions in lib/actions-affiliate.ts.
7	//
8	// Also holds the Creator Partner Program's PARTNER LOGIN INVITE flow
9	// (adminCreatePartnerInvite / acceptPartnerInvite / adminRevokePartnerInvite,
10	// 2026-09-26) and partial-payout recording (adminRecordPartnerPayout) — the two
11	// admin-facing gaps the owner's spec called out: today `adminCreatePartner`
12	// only LINKS an existing account by email, and `adminSettlePartnerCommission`
13	// only supports settling the FULL accrued balance at once.
14	
15	import { revalidatePath } from "next/cache";
16	import { redirect } from "next/navigation";
17	import { randomBytes, createHash } from "node:crypto";
18	import bcrypt from "bcryptjs";
19	import { db } from "./db";
20	import { requireArea } from "./rbac";
21	import { createSession } from "./auth";
22	
23	/** Normalise a partner code: uppercase, alphanumerics/dash, trimmed. */
24	function normalizeCode(raw: string): string {
25	  return raw
26	    .trim()
27	    .toUpperCase()
28	    .replace(/[^A-Z0-9-]/g, "")
29	    .slice(0, 32);
30	}
31	
32	/** Clamp a percent to a sane 0–90 range (integer-ish, 2dp). */
33	function clampRate(raw: number): number {
34	  if (!Number.isFinite(raw)) return 0;
35	  return Math.min(90, Math.max(0, Math.round(raw * 100) / 100));
36	}
37	
38	// ---------- Create a partner ----------
39	
40	export async function adminCreatePartner(
41	  _prev: unknown,
42	  formData: FormData
43	): Promise<{ error?: string; ok?: boolean }> {
44	  const admin = await requireArea("billing");
45	
46	  const name = String(formData.get("name") ?? "").trim();
47	  const code = normalizeCode(String(formData.get("code") ?? ""));
48	  const contactEmail = String(formData.get("contactEmail") ?? "").trim() || null;
49	  const rate = clampRate(Number(formData.get("commissionRatePct")));
50	
51	  if (!name) return { error: "Partner name is required." };
52	  if (code.length < 3) return { error: "Code must be at least 3 characters (A–Z, 0–9, dash)." };
53	  if (rate <= 0) return { error: "Commission rate must be greater than 0%." };
54	
55	  const clash = await db.referralPartner.findUnique({ where: { code } });
56	  if (clash) return { error: "That code is already in use." };
57	
58	  // Optional: link the partner to an existing user account (by email) so they can
59	  // sign in and see their portal. Silently skipped if no such user.
60	  const linkEmail = String(formData.get("linkEmail") ?? "").trim().toLowerCase();
61	  let userId: string | null = null;
62	  if (linkEmail) {
63	    const u = await db.user.findUnique({ where: { email: linkEmail }, select: { id: true } });
64	    if (!u) return { error: `No user account found for ${linkEmail}.` };
65	    const taken = await db.referralPartner.findUnique({ where: { userId: u.id } });
66	    if (taken) return { error: "That user is already a partner." };
67	    userId = u.id;
68	  }
69	
70	  const partner = await db.referralPartner.create({
71	    data: { name, code, contactEmail, commissionRatePct: rate, userId, status: "ACTIVE" },
72	  });
73	  await db.auditLog.create({
74	    data: {
75	      userId: admin.id,
76	      action: "partner.create",
77	      detail: `${partner.name} (${partner.code}) @ ${rate}%`,
78	    },
79	  });
80	  revalidatePath("/admin/partners");
81	  return { ok: true };
82	}
83	
84	// ---------- Update rate / status ----------
85	
86	export async function adminUpdatePartner(
87	  id: string,
88	  patch: { commissionRatePct?: number; status?: string }
89	): Promise<{ error?: string; ok?: boolean }> {
90	  const admin = await requireArea("billing");
91	  const partner = await db.referralPartner.findUnique({ where: { id } });
92	  if (!partner) return { error: "Partner not found." };
93	
94	  const data: { commissionRatePct?: number; status?: string } = {};
95	  if (patch.commissionRatePct != null) {
96	    const rate = clampRate(patch.commissionRatePct);
97	    if (rate <= 0) return { error: "Commission rate must be greater than 0%." };
98	    data.commissionRatePct = rate;
99	  }
100	  if (patch.status != null) {
101	    if (patch.status !== "ACTIVE" && patch.status !== "PAUSED") {
102	      return { error: "Invalid status." };
103	    }
104	    data.status = patch.status;
105	  }
106	  if (Object.keys(data).length === 0) return { error: "Nothing to update." };
107	
108	  await db.referralPartner.update({ where: { id }, data });
109	  await db.auditLog.create({
110	    data: {
111	      userId: admin.id,
112	      action: "partner.update",
113	      detail: `${partner.code} ${JSON.stringify(data)}`,
114	    },
115	  });
116	  revalidatePath("/admin/partners");
117	  revalidatePath(`/admin/partners/${id}`);
118	  return { ok: true };
119	}
120	
121	// ---------- Attach / detach a customer ----------
122	
123	/**
124	 * Attach a customer (by email) to a partner for life. Enforces the single-partner
125	 * rule (a customer already attached to a partner cannot be moved — the unique
126	 * `customerId` also hard-stops it) so attribution is never silently reassigned.
127	 */
128	export async function adminAttachCustomer(
129	  partnerId: string,
130	  email: string
131	): Promise<{ error?: string; ok?: boolean }> {
132	  const admin = await requireArea("billing");
133	  const partner = await db.referralPartner.findUnique({ where: { id: partnerId } });
134	  if (!partner) return { error: "Partner not found." };
135	
136	  const customer = await db.user.findUnique({
137	    where: { email: email.trim().toLowerCase() },
138	    select: { id: true },
139	  });
140	  if (!customer) return { error: "No customer found with that email." };
141	  if (partner.userId && partner.userId === customer.id) {
142	    return { error: "A partner cannot be attached to their own account." };
143	  }
144	
145	  const existing = await db.partnerCustomer.findUnique({
146	    where: { customerId: customer.id },
147	    include: { partner: { select: { name: true } } },
148	  });
149	  if (existing) {
150	    return existing.partnerId === partnerId
151	      ? { error: "That customer is already attached to this partner." }
152	      : { error: `That customer is already attached to ${existing.partner.name}.` };
153	  }
154	
155	  await db.partnerCustomer.create({ data: { partnerId, customerId: customer.id } });
156	  await db.auditLog.create({
157	    data: { userId: admin.id, action: "partner.attach", detail: `${partner.code} <- ${email}` },
158	  });
159	  revalidatePath(`/admin/partners/${partnerId}`);
160	  return { ok: true };
161	}
162	
163	/**
164	 * Detach a customer from a partner. Historical commission rows are LEFT INTACT
165	 * (they record charges that really happened); only the forward attachment is
166	 * removed, so no new commission accrues for this customer afterwards.
167	 */
168	export async function adminDetachCustomer(
169	  attachmentId: string
170	): Promise<{ error?: string; ok?: boolean }> {
171	  const admin = await requireArea("billing");
