189	/**
190	 * Mark all currently-ACCRUED commission for a partner as PAID, stamping `paidAt`,
191	 * AND record one `PartnerPayout` for the partner's real outstanding balance (see
192	 * PartnerPayout's own doc comment for why the real balance is
193	 * lifetime-earned-minus-payouts, not a sum of ACCRUED rows — a prior PARTIAL
194	 * payout via `adminRecordPartnerPayout` already reduced it). This records a
195	 * settlement OUTSIDE the wallet (partners are typically paid by bank transfer /
196	 * invoice), so unlike the affiliate cash-out it moves no wallet balance.
197	 */
198	export async function adminSettlePartnerCommission(
199	  partnerId: string
200	): Promise<{ error?: string; ok?: boolean; count?: number; cents?: number }> {
201	  const admin = await requireArea("billing");
202	  const partner = await db.referralPartner.findUnique({ where: { id: partnerId } });
203	  if (!partner) return { error: "Partner not found." };
204	
205	  const { computePartnerSummary } = await import("./partner-commission");
206	  const summary = await computePartnerSummary(partnerId);
207	  const cents = summary?.outstandingCents ?? 0;
208	  const agg = await db.partnerCommission.aggregate({
209	    where: { partnerId, status: "ACCRUED" },
210	    _count: true,
211	  });
212	  const count = agg._count ?? 0;
213	  if (cents <= 0) return { error: "Nothing to settle — no outstanding balance." };
214	
215	  await db.$transaction([
216	    db.partnerCommission.updateMany({
217	      where: { partnerId, status: "ACCRUED" },
218	      data: { status: "PAID", paidAt: new Date() },
219	    }),
220	    db.partnerPayout.create({
221	      data: { partnerId, amountCents: cents, note: "Full settlement", createdById: admin.id },
222	    }),
223	  ]);
224	  await db.auditLog.create({
225	    data: {
226	      userId: admin.id,
227	      action: "partner.settle",
228	      detail: `${partner.code}: ${count} rows, $${(cents / 100).toFixed(2)}`,
229	    },
230	  });
231	  revalidatePath(`/admin/partners/${partnerId}`);
232	  revalidatePath("/admin/partners");
233	  return { ok: true, count, cents };
234	}
