278	// ---------- Partner login invites (a brand-new account, not a link) ----------
279	
280	const PARTNER_INVITE_TTL_HOURS = 72;
281	
282	/**
283	 * Invite a brand-new (non-customer) login for a partner who doesn't have an
284	 * Nxeon account yet — the gap `adminCreatePartner`'s `linkEmail` field can't
285	 * fill (it only links an EXISTING account). Mirrors `inviteMember`'s token/hash/
286	 * expiry mechanics (lib/actions-teams.ts) with one real difference: the invitee
287	 * has no account to sign in with yet, so `acceptPartnerInvite` below creates one
288	 * — it cannot require `requireUser()` first.
289	 *
290	 * Deliberately DOES check whether the address already has an account (unlike
291	 * `inviteMember`'s enumeration-safe design) — this is an admin-only action
292	 * against an address the admin themself typed, not a customer-facing endpoint
293	 * an attacker could probe, and the check exists to point the admin at the right
294	 * tool (`linkEmail`) instead of silently minting an invite that can never be
295	 * redeemed (acceptPartnerInvite refuses if the address already has an account).
296	 */
297	export async function adminCreatePartnerInvite(
298	  partnerId: string,
299	  email: string
300	): Promise<{ error?: string; ok?: boolean; message?: string }> {
301	  const admin = await requireArea("billing");
302	  const partner = await db.referralPartner.findUnique({ where: { id: partnerId } });
303	  if (!partner) return { error: "Partner not found." };
304	  if (partner.userId) return { error: "This partner already has a login." };
305	
306	  const invitedEmail = String(email ?? "").trim().toLowerCase();
307	  if (!invitedEmail || !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(invitedEmail)) {
308	    return { error: "Enter a valid email address." };
309	  }
310	  const existingUser = await db.user.findUnique({ where: { email: invitedEmail }, select: { id: true } });
311	  if (existingUser) {
312	    return { error: `An account already exists for ${invitedEmail} — use "Link existing user by email" instead.` };
313	  }
314	
315	  const token = randomBytes(32).toString("base64url");
316	  const tokenHash = createHash("sha256").update(token).digest("hex");
317	  const expiresAt = new Date(Date.now() + PARTNER_INVITE_TTL_HOURS * 60 * 60 * 1000);
318	
319	  await db.partnerInvite.create({
320	    data: { partnerId, email: invitedEmail, tokenHash, invitedById: admin.id, expiresAt },
321	  });
322	
323	  const base = (process.env.APP_URL ?? "https://nxeon.cloud").replace(/\/+$/, "");
324	  const acceptUrl = `${base}/partner/invite/accept?token=${encodeURIComponent(token)}`;
325	
326	  const { sendMail, emails } = await import("./mailer");
327	  const tpl = emails.genericNotification({
328	    heading: `You're invited to become an Nxeon Partner`,
329	    message:
330	      `Nxeon has invited you to set up your Partner login for <b>${partner.name}</b> (code <b>${partner.code}</b>). ` +
331	      `Set a password to access your real-time click/signup/conversion tracking, your commission balance and payout ` +
332	      `history, and your partner link — <code>${base}/partner/${partner.code}</code>. ` +
333	      `This invitation link expires in ${PARTNER_INVITE_TTL_HOURS} hours.`,
334	    ctaLabel: "Set up your Partner account",
335	    ctaUrl: acceptUrl,
336	  });
337	  const sent = await sendMail({ to: invitedEmail, subject: tpl.subject, html: tpl.html, template: tpl.template });
338	  if (!sent) {
339	    return { error: "We couldn't send that invitation email. Check mail settings and try again." };
340	  }
341	
342	  await db.auditLog.create({
343	    data: { userId: admin.id, action: "partner.invite_sent", detail: `${partner.code} -> ${invitedEmail}` },
344	  });
345	  revalidatePath(`/admin/partners/${partnerId}`);
346	  return { ok: true, message: `Invitation emailed to ${invitedEmail}. It expires in ${PARTNER_INVITE_TTL_HOURS} hours.` };
347	}
