363	/**
364	 * Redeem a partner invite: create the new account (no `requireUser()` — the
365	 * whole point is this person has no session yet), link it to the partner, sign
366	 * them in, and mark the invite accepted. Public (no auth required to CALL this
367	 * action — a signed-in session is what it CREATES), but the token is the only
368	 * thing that authorises anything, exactly like acceptInvite's team-invite
369	 * counterpart.
370	 */
371	export async function acceptPartnerInvite(
372	  _prev: unknown,
373	  formData: FormData
374	): Promise<{ error?: string; ok?: boolean }> {
375	  const token = String(formData.get("token") ?? "");
376	  const name = String(formData.get("name") ?? "").trim();
377	  const password = String(formData.get("password") ?? "");
378	
379	  if (!token) return { error: "Missing invitation token." };
380	  if (!name) return { error: "Enter your name." };
381	  if (password.length < 8 || !/[a-zA-Z]/.test(password) || !/[0-9]/.test(password)) {
382	    return { error: "Password must be at least 8 characters and include a letter and a number." };
383	  }
384	
385	  const tokenHash = createHash("sha256").update(token).digest("hex");
386	  const invite = await db.partnerInvite.findUnique({ where: { tokenHash } });
387	  if (!invite) return { error: "This invitation link is invalid." };
388	  if (invite.revokedAt) return { error: "This invitation has been cancelled. Ask for a new one." };
389	  if (invite.acceptedAt) return { error: "This invitation has already been used. Sign in instead." };
390	  if (invite.expiresAt < new Date()) return { error: "This invitation link has expired. Ask for a new one." };
391	  // CREATOR invites carry no partner yet — they're claimed on /partner/claim.
392	  if (invite.kind === "CREATOR" || !invite.partnerId) return { error: "This invitation is claimed from your account — open the link from your email again." };
393	  const invitePartnerId = invite.partnerId;
394	
395	  const partner = await db.referralPartner.findUnique({ where: { id: invitePartnerId } });
396	  if (!partner) return { error: "That partner record no longer exists." };
397	  if (partner.userId) return { error: "This partner already has a login. Sign in instead." };
398	
399	  const existing = await db.user.findUnique({ where: { email: invite.email }, select: { id: true } });
400	  if (existing) {
401	    return { error: "An account with that email already exists. Sign in and contact support to link it." };
402	  }
403	
404	  const user = await db.$transaction(async (tx) => {
405	    const created = await tx.user.create({
406	      data: {
407	        email: invite.email,
408	        name,
409	        passwordHash: await bcrypt.hash(password, 12),
410	      },
411	    });
412	    // Guarded: if the code raced with `adminCreatePartner`'s own linkEmail path,
413	    // the unique `userId` on ReferralPartner stops a partner ever being linked
414	    // to two accounts (the update simply fails to find a still-unlinked row).
415	    const linked = await tx.referralPartner.updateMany({
416	      where: { id: invitePartnerId, userId: null },
417	      data: { userId: created.id },
418	    });
419	    if (linked.count !== 1) throw new Error("PARTNER_ALREADY_LINKED");
420	    await tx.partnerInvite.update({ where: { id: invite.id }, data: { acceptedAt: new Date() } });
421	    return created;
422	  }).catch((e) => {
423	    if (e instanceof Error && e.message === "PARTNER_ALREADY_LINKED") return null;
424	    throw e;
425	  });
426	
427	  if (!user) return { error: "This partner already has a login. Sign in instead." };
428	
429	  await db.auditLog.create({
430	    data: { userId: user.id, action: "partner.invite_accepted", detail: partner.code },
431	  });
432	  await createSession(user.id);
433	  redirect("/dashboard/partner");
434	}
