 * can be traced, otherwise performs a wallet-only refund (see server action).
 */
export function RefundForm({
  userId,
  defaultAmount,
  invoiceId,
}: {
  userId: string;
  defaultAmount?: number;
  /**
   * The invoice this refund is FOR. Without it the action cannot tell which charge
   * to reverse and fell back to "most recent top-up, any amount" — so refunding a
   * $24 March invoice issued $24 against a $200 July top-up and left the invoice
   * reading PAID. Always pass it when the form is rendered under an invoice.
