/// The partner commission LEDGER. Two kinds of row, both keyed to an invoice:
///
///  - The ORIGINAL accrual (`kind` ORDER | RENEWAL | CHARGE, `reversalKey` ""):
///    one per qualifying charge. `@@unique([invoiceId, reversalKey])` with every
///    original carrying the SAME empty key means at most one original can ever
///    exist per invoice — exactly the guarantee the old bare `invoiceId @unique`
///    gave — so a retried/duplicated accrual (inline hook + background sweep) can
///    never double-pay a partner.
///  - A REVERSAL (`kind` REFUND, negative `amountCents`/`baseCents`, `reversalKey`
///    = a stable id for ONE refund/chargeback event, e.g. `ledger:<cumulative
///    refunded cents>` or `job:<id>`): written by lib/partner-commission.ts
///    `reversePartnerCommissionForRefund` when the charge is refunded AFTER its
///    commission was already paid out (or partially refunded), per the owner's
///    rule (2026-09-29): a refund/chargeback comes off the commission earned;
///    unpaid -> off what's owed now (the original is VOIDed), already paid out ->
///    off the partner's balance at the next settlement (this negative ACCRUED row
///    nets into it). The partner is never billed to pay money back. The unique
///    key makes each event reverse at most once, while still allowing several
///    partial refunds on one invoice (an ordinary support sequence) each to get
///    their own immutable row — a settled row is never rewritten.
///
/// `baseCents` and `ratePct` are snapshotted at accrual so the ledger is a
/// durable record independent of later rate changes.
model PartnerCommission {
  id          String          @id @default(cuid())
  partnerId   String
  partner     ReferralPartner @relation(fields: [partnerId], references: [id], onDelete: Cascade)
  customerId  String
  customer    User            @relation("PartnerCommissions", fields: [customerId], references: [id], onDelete: Cascade)
  invoiceId   String
  invoice     Invoice         @relation(fields: [invoiceId], references: [id], onDelete: Cascade)
  // Net (pre-tax) charge the commission was computed on, the frozen rate, and the
  // resulting commission — all snapshotted at accrual. NEGATIVE on a REFUND row.
  baseCents   Int
  ratePct     Float
  amountCents Int
  kind        String          @default("CHARGE") // ORDER | RENEWAL | CHARGE | REFUND
  status      String          @default("ACCRUED") // ACCRUED | PAID | VOID
  // "" on the original accrual row; a per-refund-event idempotency key on a
  // REFUND row. See the model doc above.
  reversalKey String          @default("")
  createdAt   DateTime        @default(now())
  paidAt      DateTime?

  @@unique([invoiceId, reversalKey])
  @@index([partnerId, status])
  @@index([customerId])
}

