186	 * renewals) without each charge site needing to know about the partner program,
187	 * and it self-heals any charge the inline hooks missed. Idempotent.
188	 *
189	 * Wired into the billing worker loop (worker/index.ts) alongside billingSweep.
190	 * `sinceDays` bounds the scan so it stays cheap on each pass; anything older than
191	 * that has long since been accrued on a prior sweep.
192	 */
193	export async function reconcilePartnerCommissions(
194	  opts: { sinceDays?: number; limit?: number } = {}
195	): Promise<{ scanned: number; accrued: number }> {
196	  const sinceDays = opts.sinceDays ?? 45;
197	  const limit = opts.limit ?? 500;
198	  const since = new Date(Date.now() - sinceDays * 24 * 60 * 60_000);
199	
200	  // Only invoices belonging to an attached customer are candidates. We join through
201	  // PartnerCustomer so partner-less customers (the vast majority) are never scanned.
202	  const invoices = await db.invoice.findMany({
203	    where: {
204	      status: "PAID",
205	      partnerCommissions: { none: { reversalKey: "" } },
206	      createdAt: { gte: since },
207	      user: { partnerAttachment: { isNot: null } },
208	    },
209	    orderBy: { createdAt: "asc" },
210	    take: limit,
211	    select: { id: true, userId: true, status: true, amountCents: true, taxCents: true, description: true, createdAt: true, dedicatedIpCents: true },
212	  });
213	
214	  let accrued = 0;
215	  for (const inv of invoices) {
216	    try {
217	      const res = await accrueCommissionForInvoice(inv);
218	      if (res) accrued++;
219	    } catch (e) {
220	      // One bad invoice must never abort the sweep.
221	      console.error("[partner-commission] sweep accrual failed for invoice", inv.id, e);
222	    }
223	  }
224	  return { scanned: invoices.length, accrued };
225	}
