227	// ---------- Partner-facing summary ----------
228	
229	export type PartnerSummary = {
230	  partnerId: string;
231	  name: string;
232	  code: string;
233	  commissionRatePct: number;
234	  status: string;
235	  customerCount: number;
236	  /** Lifetime commission ever EARNED (every non-VOID PartnerCommission row), in cents. */
237	  lifetimeCents: number;
238	  /** lifetimeCents minus every real PartnerPayout ever recorded — the real balance owed. */
239	  outstandingCents: number;
240	  /** Sum of every real PartnerPayout ever recorded (full settlements + partial payouts). */
241	  paidCents: number;
242	};
243	
244	/**
245	 * Roll up a partner's standing: attached-customer count, lifetime commission
246	 * EARNED, and the real balance owed.
247	 *
248	 * `paidCents`/`outstandingCents` are computed from `PartnerPayout` — the ledger of
249	 * REAL payments made — not from summing PartnerCommission rows whose `status`
250	 * happens to read PAID. Two ledgers, "earned" (PartnerCommission) and "paid"
251	 * (PartnerPayout), net balance = earned − paid: the only way to honestly support
252	 * a PARTIAL payout ("$340 today even though $412 is accrued" — the owner's own
253	 * example) without inventing a way to mark a fractional set of commission rows
254	 * paid. A full settlement (adminSettlePartnerCommission) still flips every
255	 * ACCRUED row to PAID for the per-row ledger display, so for the common case the
256	 * two views agree; see PartnerPayout's own doc comment on the model.
257	 */
258	export async function computePartnerSummary(partnerId: string): Promise<PartnerSummary | null> {
259	  const partner = await db.referralPartner.findUnique({ where: { id: partnerId } });
260	  if (!partner) return null;
261	
262	  const [customerCount, lifetimeAgg, payoutAgg] = await Promise.all([
263	    db.partnerCustomer.count({ where: { partnerId } }),
264	    db.partnerCommission.aggregate({
265	      where: { partnerId, status: { not: "VOID" } },
266	      _sum: { amountCents: true },
267	    }),
268	    db.partnerPayout.aggregate({
269	      where: { partnerId },
270	      _sum: { amountCents: true },
271	    }),
272	  ]);
273	
274	  const lifetimeCents = lifetimeAgg._sum.amountCents ?? 0;
275	  const paidCents = payoutAgg._sum.amountCents ?? 0;
276	  const outstandingCents = Math.max(0, lifetimeCents - paidCents);
277	  return {
278	    partnerId: partner.id,
279	    name: partner.name,
280	    code: partner.code,
281	    commissionRatePct: partner.commissionRatePct,
282	    status: partner.status,
283	    customerCount,
284	    lifetimeCents,
285	    outstandingCents,
286	    paidCents,
287	  };
288	}
