  // job, a quick cancel) can beat both the inline accrual hook and the sweep. If
  // we skipped here, the sweep would later accrue the FULL commission on a charge
  // that was already refunded, with nothing left to reverse it. Idempotent, and a
  // no-op for anything accrueCommissionForInvoice wouldn't accrue anyway (no
  // partner, paused partner, pre-attachment charge, non-PAID invoice).
  if (invoice.status === "PAID") await accrueCommissionForInvoice(invoice);

  const original = await db.partnerCommission.findUnique({
    where: { invoiceId_reversalKey: { invoiceId, reversalKey: "" } },
    select: { id: true, amountCents: true },
  });
  // The overwhelmingly common case: this charge never earned any commission.
  if (!original || original.amountCents <= 0) return null;

  const result = await db.$transaction(async (tx) => {
    await tx.$queryRaw`SELECT id FROM "PartnerCommission" WHERE id = ${original.id} FOR UPDATE`;
    const fresh = await tx.invoice.findUnique({ where: { id: invoiceId }, select: REVERSAL_INVOICE_SELECT });
    const rows = await tx.partnerCommission.findMany({ where: { invoiceId } });
    const orig = rows.find((r) => r.reversalKey === "");
    if (!fresh || !orig) return null;

    const p = plan({ invoice: fresh, rows });
    if (!p || !p.key || p.refundCents <= 0) return null;
    // This exact refund event was already reversed — idempotent re-call.
    if (rows.some((r) => r.reversalKey === p.key)) return null;

    const alreadyReversed =
      (orig.status === "VOID" ? orig.amountCents : 0) +
      rows.filter((r) => r.reversalKey !== "").reduce((s, r) => s - r.amountCents, 0);
    const delta = commissionReversalCents({
      commissionCents: orig.amountCents,
      alreadyReversedCents: alreadyReversed,
      invoiceCents: fresh.amountCents,
      refundCents: p.refundCents,
    });
    if (delta <= 0) return null;

    // Not yet paid out and the whole thing is being reversed: it simply comes off
    // what's owed — void the original rather than stacking a +X/-X pair.
    if (orig.status === "ACCRUED" && alreadyReversed === 0 && delta === orig.amountCents) {
      await tx.partnerCommission.update({ where: { id: orig.id }, data: { status: "VOID" } });
      return { partnerId: orig.partnerId, commissionId: orig.id, mode: "VOIDED" as const, reversedCents: delta, key: p.key };
    }

    // Already paid out (or a partial refund): a negative row that nets against
    // the partner's next settlement. Same partner/customer/invoice as the
    // original; base scaled by the same share so the ledger's "Charge (net)"
    // column stays consistent with the reversed amount.
    const row = await tx.partnerCommission.create({
      data: {
        partnerId: orig.partnerId,
        customerId: orig.customerId,
        invoiceId,
        baseCents: -Math.round((orig.baseCents * delta) / orig.amountCents),
        ratePct: orig.ratePct,
        amountCents: -delta,
        kind: REFUND_KIND,
        status: "ACCRUED",
        reversalKey: p.key,
      },
      select: { id: true },
    });
    return {
      partnerId: orig.partnerId,
      commissionId: orig.id,
      mode: "REFUND_ROW" as const,
      reversedCents: delta,
      reversalId: row.id,
      key: p.key,
    };
  });
  if (!result) return null;

  // Ops trail. userId deliberately null: AuditLog rows keyed to the CUSTOMER feed
  // their own Activity screen, and a customer must never see partner economics.
  const { key, ...reversal } = result;
  await db.auditLog
    .create({
      data: {
        userId: null,
        action: "partner.commission_reversed",
        category: "billing",
        detail:
          `invoice #${invoice.number} partner=${reversal.partnerId} ${reversal.mode} ` +
          `-$${(reversal.reversedCents / 100).toFixed(2)} [${key}]${reason ? ` — ${reason}` : ""}`.slice(0, 500),
      },
    })
    .catch(() => {});
  return reversal;
}

/**
 * Reverse the partner commission on ONE refund / chargeback event against an
 * invoice. `refundCents` is what THIS event returned to the customer, on the same
 * gross (tax-inclusive) basis as `Invoice.amountCents`; `key` is a stable id for
 * the event (e.g. `job:<jobId>`, `cancel:<serverId>`) — re-calling with the same
 * key is a no-op, so a retried hook can never double-reverse.
 *
 * Returns null for every "nothing to do" case (no such invoice, the charge never
 * earned commission, already reversed, nothing left to reverse). Unexpected DB
 * errors propagate — refund paths call it through `reverseCommissionSafely`.
 */
export async function reversePartnerCommissionForRefund(opts: {
  invoiceId: string;
  refundCents: number;
  key: string;
  reason?: string;
}): Promise<CommissionReversal | null> {
  if (!opts.key || !(opts.refundCents > 0)) return null;
  return applyCommissionReversal(
    opts.invoiceId,
    () => ({ key: opts.key, refundCents: opts.refundCents }),
    opts.reason,
  );
}

/**
 * Bring an invoice's commission in line with the refunds recorded ON THE INVOICE
 * ITSELF (`refundedCents` / REFUNDED status — see invoiceLedgerRefundedCents).
 * Used by the paths that record their refund there (admin refundPayment, a failed
 * domain transfer) and by the sweep backstop. Keyed `ledger:<cumulative refunded
 * cents>`: the running total only ever grows, so each refund step gets its own
 * key, and the amount reversed is always "cumulative refunded minus what earlier
 * ledger reversals already covered" — a step whose own hook never ran is picked
 * up by the next one (or the sweep) instead of being lost.
 */
export async function syncPartnerCommissionWithInvoiceRefunds(
  invoiceId: string,
  reason?: string,
): Promise<CommissionReversal | null> {
  return applyCommissionReversal(
    invoiceId,
    ({ invoice, rows }) => {
      const refunded = invoiceLedgerRefundedCents(invoice);
      if (refunded <= 0) return null;
      const covered = rows.reduce((max, r) => {
        if (!r.reversalKey.startsWith("ledger:")) return max;
        const n = Number(r.reversalKey.slice("ledger:".length));
        return Number.isFinite(n) ? Math.max(max, n) : max;
      }, 0);
      if (refunded <= covered) return null;
      return { key: `ledger:${refunded}`, refundCents: refunded - covered };
    },
    reason,
  );
}

/**
 * Never-throwing wrapper for the refund hook sites. A commission-ledger hiccup
 * must never fail, or roll back, a customer's refund — the refund has already
 * committed by the time this runs. A failure is logged AND written to AuditLog
 * (`partner.commission_reversal_failed`) so it's visible to ops rather than lost.
 */
export async function reverseCommissionSafely(
  label: string,
  run: () => Promise<CommissionReversal | null>,
): Promise<CommissionReversal | null> {
  try {
    return await run();
  } catch (e) {
    console.error("[partner-commission] reversal failed:", label, e);
    await db.auditLog
      .create({
        data: {
          userId: null,
          action: "partner.commission_reversal_failed",
          category: "billing",
          detail: `${label}: ${(e as Error)?.message ?? String(e)}`.slice(0, 500),
        },
      })
      .catch(() => {});
    return null;
  }
}

