/**
 * The invoice that paid for a server's CURRENT term — its most recent order or
 * renewal invoice — or null when there is none (a free server, or a game server
 * ordered before game orders got invoices). Same no-FK convention as
 * resolveServerLifetimeSpendCents above, narrowed to the TERM charges: the order
 * (`<plan> VPS (<host>) — …` / `<plan> Game Server (<host>) — …`) and every
 * renewal (`Renewal: <label> (<host>)…`) are the only invoice descriptions that
 * wrap the hostname in parentheses; add-on/upgrade invoices use ` — <host>`.
 * Rename-safe via `previousHostnames`, scoped to the owner and to invoices
 * written no earlier than the server itself (so a deleted server that once used
 * the same hostname can't match). REFUNDED is included so an invoice an admin
 * already refunded in full is still the one found — never an older one behind it.
 *
 * Used to attach the partner-commission reversal to the right charge when a
 * self-serve cancellation refunds the unused term (actions-server-lifecycle.ts).
 */
export async function latestServerTermInvoiceId(server: {
  userId: string;
  hostname: string;
  previousHostnames: string[];
  createdAt: Date;
}): Promise<string | null> {
  const names = [server.hostname, ...(server.previousHostnames ?? [])].filter((h) => !!h);
  if (names.length === 0) return null;
  const inv = await db.invoice.findFirst({
    where: {
      userId: server.userId,
      status: { in: ["PAID", "REFUNDED"] },
      createdAt: { gte: new Date(server.createdAt.getTime() - 60_000) },
      OR: names.map((h) => ({ description: { contains: `(${h})` } })),
    },
    orderBy: { createdAt: "desc" },
    select: { id: true },
  });
  return inv?.id ?? null;
}
