// ---------- Chargebacks ----------

/**
 * Record a CHARGEBACK against the partner commission earned on an invoice. The
 * owner's rule (2026-09-29) treats a chargeback exactly like a refund: it comes
 * off the commission — voided if not yet paid out, netted off the partner's next
 * payout if it was. Refunds reverse automatically from every refund path; a
 * chargeback has no code path of its own (Stripe disputes arrive by email /
 * dashboard, and a wallet-funded invoice can't be traced back to one card charge
 * automatically), so the admin records it here from the invoice page.
 *
 * Touches ONLY the partner-commission ledger — no wallet, no card, no invoice
 * status (a disputed card charge can't be refunded through Stripe anyway, and
 * whatever happens to the customer's account is a separate, deliberate decision).
 * One chargeback per invoice (key `chargeback:<invoiceId>`), so a double-submit
 * can never reverse twice; the amount is capped at the invoice total and the
 * reversal at what's left of the commission.
 */
export async function adminReverseCommissionForChargeback(
  invoiceId: string,
  amountCents: number,
  note?: string,
): Promise<{ error?: string; ok?: boolean; message?: string }> {
  const admin = await requireArea("billing");
  const invoice = await db.invoice.findUnique({
    where: { id: invoiceId },
    select: { id: true, number: true, amountCents: true },
  });
  if (!invoice) return { error: "Invoice not found." };

  const cents = Math.round(Number(amountCents));
  if (!Number.isFinite(cents) || cents <= 0) return { error: "Enter the amount that was charged back." };
  if (cents > invoice.amountCents) {
    return { error: `That's more than the invoice total ($${(invoice.amountCents / 100).toFixed(2)}).` };
  }

  const { reversePartnerCommissionForRefund } = await import("./partner-commission");
  const trimmed = note?.trim().slice(0, 200) || "";
  const res = await reversePartnerCommissionForRefund({
    invoiceId,
    refundCents: cents,
    key: `chargeback:${invoiceId}`,
    reason: `chargeback${trimmed ? `: ${trimmed}` : ""}`,
  });
  if (!res) {
    return {
      error:
        "Nothing to reverse — this invoice's commission has already been fully reversed, or a chargeback " +
        "was already recorded for it.",
    };
  }

  await db.auditLog.create({
    data: {
      userId: admin.id,
      action: "partner.chargeback",
      detail: `invoice #${invoice.number}: $${(cents / 100).toFixed(2)} charged back -> commission -$${(res.reversedCents / 100).toFixed(2)} (${res.mode})${trimmed ? ` — ${trimmed}` : ""}`,
    },
  });
  revalidatePath(`/admin/invoices/${invoiceId}`);
  revalidatePath(`/admin/partners/${res.partnerId}`);
  revalidatePath("/admin/partners");
  return {
    ok: true,
    message:
      `Partner commission reduced by $${(res.reversedCents / 100).toFixed(2)}` +
      (res.mode === "VOIDED" ? " — it hadn't been paid out yet, so it was voided." : " — deducted from their next payout."),
  };
}

