import { test } from "node:test";
import assert from "node:assert/strict";
import { commissionReversalCents, invoiceLedgerRefundedCents } from "../lib/partner-commission.ts";

/**
 * Refund / chargeback reversal of partner commission (owner's rule, 2026-09-29):
 * a refund comes off the commission earned on that charge, in proportion to how
 * much of the charge was refunded, and never more than what's left of it. Pure
 * arithmetic, no DB — the DB branches (ACCRUED -> VOID, PAID -> negative REFUND
 * row) are verified against the staging database, see docs/DOCUMENTATION.md.
 */

test("full refund reverses the whole commission, exactly", () => {
  assert.equal(
    commissionReversalCents({ commissionCents: 560, alreadyReversedCents: 0, invoiceCents: 1399, refundCents: 1399 }),
    560,
  );
  // Refund amount above the invoice (defensive): still exactly the commission.
  assert.equal(
    commissionReversalCents({ commissionCents: 560, alreadyReversedCents: 0, invoiceCents: 1399, refundCents: 5000 }),
    560,
  );
});

test("partial refund reverses proportionally to the gross refunded share", () => {
  // $13.99 charge, $5.60 commission, $7.00 refunded -> round(560 * 700 / 1399) = 280
  assert.equal(
    commissionReversalCents({ commissionCents: 560, alreadyReversedCents: 0, invoiceCents: 1399, refundCents: 700 }),
    280,
  );
  // A 72h cancellation refunding 97% of a $10 term with a $4 commission -> $3.88.
  assert.equal(
    commissionReversalCents({ commissionCents: 400, alreadyReversedCents: 0, invoiceCents: 1000, refundCents: 970 }),
    388,
  );
});

test("successive partial refunds can never reverse more than was earned", () => {
  const commissionCents = 560;
  const invoiceCents = 1399;
  const first = commissionReversalCents({ commissionCents, alreadyReversedCents: 0, invoiceCents, refundCents: 1000 });
  const second = commissionReversalCents({ commissionCents, alreadyReversedCents: first, invoiceCents, refundCents: 1000 });
  assert.equal(first, 400);
  assert.equal(second, 160); // capped at what's left, not another 400
  assert.equal(first + second, commissionCents);
  const third = commissionReversalCents({ commissionCents, alreadyReversedCents: first + second, invoiceCents, refundCents: 399 });
  assert.equal(third, 0);
});

test("nothing to reverse: no commission, no refund, zero-value invoice", () => {
  assert.equal(commissionReversalCents({ commissionCents: 0, alreadyReversedCents: 0, invoiceCents: 1000, refundCents: 1000 }), 0);
  assert.equal(commissionReversalCents({ commissionCents: 200, alreadyReversedCents: 0, invoiceCents: 1000, refundCents: 0 }), 0);
  assert.equal(commissionReversalCents({ commissionCents: 200, alreadyReversedCents: 0, invoiceCents: 0, refundCents: 100 }), 0);
  assert.equal(commissionReversalCents({ commissionCents: 200, alreadyReversedCents: 200, invoiceCents: 1000, refundCents: 1000 }), 0);
});

test("invoice ledger refunded amount: running total, or the whole invoice once REFUNDED", () => {
  assert.equal(invoiceLedgerRefundedCents({ status: "PAID", amountCents: 1000, refundedCents: 0 }), 0);
  assert.equal(invoiceLedgerRefundedCents({ status: "PAID", amountCents: 1000, refundedCents: 250 }), 250);
  // refundPayment's full refund: status REFUNDED and refundedCents == amount.
  assert.equal(invoiceLedgerRefundedCents({ status: "REFUNDED", amountCents: 1000, refundedCents: 1000 }), 1000);
  // settleFailedTransferIn: flips to REFUNDED without a running total.
  assert.equal(invoiceLedgerRefundedCents({ status: "REFUNDED", amountCents: 1000, refundedCents: 0 }), 1000);
});

