// Staging-only verification harness for the refund -> partner-commission reversal.
// Usage: DATABASE_URL=<staging> npx tsx --tsconfig <worktree>/tsconfig.json verify-refund.ts <phase>
import { readFileSync, writeFileSync, existsSync } from "node:fs";
import { randomBytes } from "node:crypto";
import { db } from "/root/nxeon-worktrees/refund-commission/lib/db";
import {
  accrueRecentCommissionsForCustomer,
  computePartnerSummary,
  reversePartnerCommissionForRefund,
  syncPartnerCommissionWithInvoiceRefunds,
  reconcilePartnerCommissions,
} from "/root/nxeon-worktrees/refund-commission/lib/partner-commission";
import { latestServerTermInvoiceId } from "/root/nxeon-worktrees/refund-commission/lib/server-spend";
import { invoiceCreateData } from "/root/nxeon-worktrees/refund-commission/lib/invoices";

const STATE = "/tmp/claude-0/-root/ec6fa978-d80b-4147-9982-eea470598e2c/scratchpad/verify-state.json";
type State = { userId: string; email: string; partnerId: string; code: string; inv: Record<string, string> };
const load = (): State => JSON.parse(readFileSync(STATE, "utf8"));
const save = (s: State) => writeFileSync(STATE, JSON.stringify(s, null, 2));

async function guard() {
  const r = await db.$queryRaw<{ current_database: string }[]>`select current_database()`;
  if (r[0]?.current_database !== "nxeon_staging") throw new Error(`REFUSING: connected to ${r[0]?.current_database}`);
}

async function mkInvoice(userId: string, description: string, cents: number) {
  const inv = await db.invoice.create({
    data: invoiceCreateData({
      userId,
      description,
      status: "PAID",
      lineItems: [{ description, qty: 1, unitCents: cents, amountCents: cents }],
    }),
    select: { id: true, number: true },
  });
  return inv.id;
}

async function summary(label: string) {
  const s = load();
  const sum = await computePartnerSummary(s.partnerId);
  const rows = await db.partnerCommission.findMany({
    where: { partnerId: s.partnerId },
    orderBy: { createdAt: "asc" },
    include: { invoice: { select: { number: true, description: true, amountCents: true, refundedCents: true, status: true } } },
  });
  const payouts = await db.partnerPayout.findMany({ where: { partnerId: s.partnerId }, orderBy: { createdAt: "asc" } });
  const name = (id: string) => Object.entries(s.inv).find(([, v]) => v === id)?.[0] ?? "?";
  console.log(`\n=== ${label} ===`);
  console.log(
    `summary: lifetime=${sum!.lifetimeCents} paid=${sum!.paidCents} balance=${sum!.balanceCents} outstanding=${sum!.outstandingCents}`,
  );
  for (const r of rows) {
    console.log(
      `  ${name(r.invoiceId).padEnd(2)} inv#${r.invoice.number} ${r.invoice.status.padEnd(8)} amt=${String(r.invoice.amountCents).padStart(5)} refunded=${String(r.invoice.refundedCents).padStart(5)} | ${r.kind.padEnd(7)} ${r.status.padEnd(7)} base=${String(r.baseCents).padStart(6)} comm=${String(r.amountCents).padStart(6)} key="${r.reversalKey}"`,
    );
  }
  for (const p of payouts) console.log(`  payout ${p.amountCents} (${p.note})`);
}

const phase = process.argv[2];
(async () => {
  await guard();
  if (phase === "seed") {
    if (existsSync(STATE)) throw new Error("state exists — already seeded");
    const tag = randomBytes(3).toString("hex");
    const email = `refund-verify-${tag}@nxeon.test`;
    const user = await db.user.create({
      data: { email, name: `Refund Verify ${tag}`, passwordHash: "!disabled-test-account", balanceCents: 20000 },
    });
    const code = `RFND${tag.toUpperCase()}`;
    const partner = await db.referralPartner.create({
      data: { name: `Refund verification (staging test) ${tag}`, code, commissionRatePct: 40, status: "ACTIVE", notes: "Staging-only test partner for fix/refund-commission-reversal verification (2026-09-29)." },
    });
    await db.partnerCustomer.create({
      data: { partnerId: partner.id, customerId: user.id, attachedAt: new Date(Date.now() - 60_000), createdAt: new Date(Date.now() - 60_000) },
    });
    const inv: Record<string, string> = {};
    inv.A = await mkInvoice(user.id, `Test VPS (rfnd-a-${tag}) — 1 month`, 1000);
    inv.B = await mkInvoice(user.id, `Test VPS (rfnd-b-${tag}) — 1 month`, 2000);
    inv.C = await mkInvoice(user.id, `Test VPS (rfnd-c-${tag}) — 1 month`, 1399);
    inv.D = await mkInvoice(user.id, `Test VPS (rfnd-d-${tag}) — 1 month`, 2500);
    inv.E = await mkInvoice(user.id, `Test VPS (rfnd-e-${tag}) — 1 month`, 1000);
    inv.F = await mkInvoice(user.id, `Extra 10 GB disk (prorated) — rfnd-e-${tag}`, 300);
    save({ userId: user.id, email, partnerId: partner.id, code, inv });
    await accrueRecentCommissionsForCustomer(user.id, 20);
    console.log(JSON.stringify({ partnerId: partner.id, code, email, inv }, null, 2));
    await summary("S0 after seed + real accrual");
  } else if (phase === "engine-accrued") {
    // cancelService-equivalent (E) and failed-job-equivalent (F), both still ACCRUED.
    const s = load();
    const tag = s.code.slice(4).toLowerCase();
    const e = await db.invoice.findUnique({ where: { id: s.inv.E }, select: { createdAt: true } });
    const found = await latestServerTermInvoiceId({
      userId: s.userId,
      hostname: `rfnd-e-${tag}`,
      previousHostnames: [],
      createdAt: new Date(e!.createdAt.getTime() - 5_000),
    });
    console.log(`latestServerTermInvoiceId -> ${found === s.inv.E ? "E (correct: the term invoice, not the later add-on F)" : found}`);
    const r1 = await reversePartnerCommissionForRefund({ invoiceId: found!, refundCents: 970, key: `cancel:verify-${tag}`, reason: "verify: cancellation refund" });
    console.log("E cancel 970/1000 ->", r1);
    const r1b = await reversePartnerCommissionForRefund({ invoiceId: found!, refundCents: 970, key: `cancel:verify-${tag}`, reason: "verify: retry" });
    console.log("E same key again (idempotent) ->", r1b);
    const r2 = await reversePartnerCommissionForRefund({ invoiceId: s.inv.F, refundCents: 300, key: `job:verify-${tag}`, reason: "verify: failed disk expansion" });
    console.log("F failed-job full refund ->", r2);
    const r2b = await reversePartnerCommissionForRefund({ invoiceId: s.inv.F, refundCents: 300, key: `job:verify-${tag}-other`, reason: "verify: another key on a voided commission" });
    console.log("F different key after VOID (nothing left) ->", r2b);
    await summary("after engine calls (E partial, F full)");
  } else if (phase === "more-earnings") {
    const s = load();
    const tag = s.code.slice(4).toLowerCase();
    s.inv.G = await mkInvoice(s.userId, `Renewal: Test (rfnd-g-${tag})`, 500);
    save(s);
    await accrueRecentCommissionsForCustomer(s.userId, 20);
    await summary("after new charge G ($5.00) accrues");
    s.inv.H = await mkInvoice(s.userId, `Renewal: Test (rfnd-h-${tag})`, 5000);
    save(s);
    await accrueRecentCommissionsForCustomer(s.userId, 20);
    await summary("after new charge H ($50.00) accrues");
  } else if (phase === "backstop") {
    const s = load();
    const tag = s.code.slice(4).toLowerCase();
    // (1) refund recorded on the invoice but its hook never ran -> sweep reverses it.
    s.inv.I = await mkInvoice(s.userId, `Test VPS (rfnd-i-${tag}) — 1 month`, 1000);
    save(s);
    await accrueRecentCommissionsForCustomer(s.userId, 20);
    await db.invoice.update({ where: { id: s.inv.I }, data: { refundedCents: 1000, status: "REFUNDED" } });
    await summary("I accrued, then refunded on the invoice with NO hook run");
    const sweep = await reconcilePartnerCommissions();
    console.log("reconcilePartnerCommissions ->", sweep);
    const sweep2 = await reconcilePartnerCommissions();
    console.log("reconcilePartnerCommissions again (idempotent) ->", sweep2);
    // (2) refunded BEFORE any accrual ran -> reversal accrues first, then reverses.
    s.inv.J = await mkInvoice(s.userId, `Test VPS (rfnd-j-${tag}) — 1 month`, 1000);
    save(s);
    const before = await db.partnerCommission.count({ where: { invoiceId: s.inv.J } });
    const rj = await reversePartnerCommissionForRefund({ invoiceId: s.inv.J, refundCents: 1000, key: `job:verify-j-${tag}`, reason: "verify: refund before accrual" });
    console.log(`J commission rows before=${before}; reversal ->`, rj);
    await summary("after backstop + refund-before-accrual");
  } else if (phase === "summary") {
    await summary(process.argv[3] ?? "summary");
  } else if (phase === "sync") {
    const s = load();
    const r = await syncPartnerCommissionWithInvoiceRefunds(s.inv[process.argv[3]], "verify: manual re-sync");
    console.log(`sync ${process.argv[3]} ->`, r);
  } else {
    console.log("phases: seed | engine-accrued | more-earnings | backstop | summary [label] | sync <X>");
  }
  await db.$disconnect();
})().catch(async (e) => {
  console.error(e);
  await db.$disconnect();
  process.exit(1);
});

